  ninfas_1 = excluded.ninfas_1,
  ninfas_2 = excluded.ninfas_2,
  ninfas_3 = excluded.ninfas_3,
  adultos = excluded.adultos,
  larvas = excluded.larvas,
  pupas = excluded.pupas,
  longitud = excluded.longitud,
  latitud = excluded.latitud
  returning id
)
